const raw = $input.item.json;
const ctx = $('Recibir Datos').item.json;

// Parse AI JSON response
let aiData = {};
let mensaje = '';

try {
  const rawText = (raw.choices?.[0]?.message?.content || raw.mensaje || '').trim();
  // Remove markdown code fences if present
  const jsonText = rawText.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/,'').trim();
  aiData = JSON.parse(jsonText);
  mensaje = (aiData.respuesta || '').trim();
} catch(e) {
  // Try to extract respuesta field with regex as last resort
  const rawText = (raw.choices?.[0]?.message?.content || raw.mensaje || '').trim();
  const match = rawText.match(/"respuesta"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  mensaje = match ? match[1].replace(/\\n/g,'\n').replace(/\\"/g,'"') : '';
}

// Fallback messages if AI failed completely
if (!mensaje) {
  const n = ctx.datosRecolectados?.nombre_cliente || '';
  const h = (new Date().getUTCHours() - 4 + 24) % 24;
  const gr = h < 12 ? 'Buenos días' : h < 19 ? 'Buenas tardes' : 'Buenas noches';
  const fallbacks = {
    PRIMER_CONTACTO:       `${gr}, soy Alex de Crating Express. ¿Con quién tengo el gusto?`,
    PEDIR_NOMBRE:          '¿Con quién tengo el gusto?',
    IDENTIFICAR_NECESIDAD: n ? `¿En qué puedo ayudarte hoy, ${n}?` : '¿En qué puedo ayudarte hoy?',
    FLUJO_CONSULTA:        '¿En qué más puedo ayudarte?',
    PEDIR_PRODUCTO:        '¿Qué artículo necesitas embalar?',
    PEDIR_MEDIDAS:         '¿Cuáles son las medidas en pulgadas? (Largo × Ancho × Alto)',
    PEDIR_TIPO_CAJON:      '¿Qué tipo de embalaje prefieres? Cajón cerrado (máxima protección + ISPM-15), jaula (más liviana) o paleta.',
    PEDIR_PROTECCION:      '¿Necesitas protección interior como foam, burbuja o esquineras? Tiene costo adicional.',
    PEDIR_FECHA:           '¿Para cuándo necesitas el embalaje?',
    LISTO_PARA_COTIZAR:    'Perfecto, ya tengo todos los datos. Un vendedor te enviará la cotización pronto.',
    POST_COTIZACION:       '¿En qué más puedo ayudarte?'
  };
  mensaje = fallbacks[ctx.proximoPaso] || '¿En qué más puedo ayudarte?';
}

// Merge AI-extracted data into datosRecolectados
const datosRecolectados = { ...(ctx.datosRecolectados || {}) };

if (aiData.nombre   && !datosRecolectados.nombre_cliente)  datosRecolectados.nombre_cliente  = aiData.nombre;
if (aiData.producto && !datosRecolectados.producto)         datosRecolectados.producto        = aiData.producto;
if (aiData.medidas  && !datosRecolectados.medidas)          datosRecolectados.medidas         = aiData.medidas;
if (aiData.tipo_cajon && !datosRecolectados.tipo_cajon)     datosRecolectados.tipo_cajon      = aiData.tipo_cajon;
if (aiData.fecha    && !datosRecolectados.fecha)            datosRecolectados.fecha           = aiData.fecha;
if (aiData.correo  && !datosRecolectados.correo_contacto)  datosRecolectados.correo_contacto = aiData.correo;
if (aiData.proteccion_extra !== null && aiData.proteccion_extra !== undefined
    && (datosRecolectados.proteccion_extra === null || datosRecolectados.proteccion_extra === undefined)) {
  datosRecolectados.proteccion_extra = aiData.proteccion_extra;
}

// Update tipo_flujo based on AI intent (only set, never override existing)
if (!datosRecolectados.tipo_flujo) {
  if (aiData.intento === 'cotizacion') datosRecolectados.tipo_flujo = 'cotizacion';
  else if (aiData.intento === 'consulta') datosRecolectados.tipo_flujo = 'consulta';
}
// If AI detected cotización while in consulta, allow upgrade
if (aiData.intento === 'cotizacion' && datosRecolectados.tipo_flujo === 'consulta') {
  datosRecolectados.tipo_flujo = 'cotizacion';
}

// Recalculate todosRecolectados with updated data
const cleanCheck = v => {
  if (typeof v === 'boolean') return v;
  if (!v || ['desconocido','null','undefined'].includes(String(v).toLowerCase().trim())) return null;
  return v;
};

const todosRecolectados = !ctx.cotizacionEnviada  // no re-trigger if already sent
  && datosRecolectados.tipo_flujo === 'cotizacion'
  && !!cleanCheck(datosRecolectados.producto)
  && !!cleanCheck(datosRecolectados.medidas)
  && !!cleanCheck(datosRecolectados.tipo_cajon)
  && datosRecolectados.proteccion_extra !== null && datosRecolectados.proteccion_extra !== undefined
  && !!cleanCheck(datosRecolectados.fecha);

// Recalculate dimensions from updated medidas
let dimensiones = ctx.dimensiones || null;
if (datosRecolectados.medidas && !dimensiones) {
  const nums = datosRecolectados.medidas.match(/(\d+(?:\.\d+)?)/g);
  if (nums && nums.length >= 3) {
    dimensiones = { largo: parseFloat(nums[0]), ancho: parseFloat(nums[1]), alto: parseFloat(nums[2]) };
  }
}

const tipoCajaApi = datosRecolectados.tipo_cajon || ctx.tipoCajaApi || null;
const proximoPaso = ctx.proximoPaso;

// Lead classification
let clasificacion = null;
if (datosRecolectados.correo_contacto && (proximoPaso === 'POST_COTIZACION' || ctx.cotizacionEnviada)) {
  clasificacion = 'Caliente';
}

let nuevoEstado = ctx.estado;
if (clasificacion === 'Caliente') nuevoEstado = 'Vendedor notificado';
else if (todosRecolectados && !ctx.cotizacionEnviada) nuevoEstado = 'Calificado';
else if (!ctx.leadId || nuevoEstado === 'Nuevo') nuevoEstado = 'En calificación';

if (mensaje.length > 3800) mensaje = mensaje.slice(0, 3750) + '…';

const ts = new Date().toISOString();
const nuevoHistorial = (ctx.historial ? ctx.historial + '\n' : '')
  + `[${ts}] Cliente: ${ctx.texto}\n[${ts}] Bot: ${mensaje}`;

// temaConsulta: save first consulta message, preserve when switching to cotización
let temaConsulta = ctx.temaConsulta || null;
if (!temaConsulta && ctx.proximoPaso === 'FLUJO_CONSULTA') {
  temaConsulta = ctx.texto || null;
}

return [{ json: {
  ...ctx,
  mensaje,
  mensajeRespuesta: mensaje,
  datosRecolectados,
  todos_recolectados: todosRecolectados,
  todosRecolectados,
  dimensiones,
  tipo_caja_api: tipoCajaApi,
  cotizador_enviado: false,
  temaConsulta,
  clasificacion,
  nuevoEstado,
  nuevoHistorial
} }];

